mapper.select:
SELECT NULL::date AS event_date, 'users' AS metric, COUNT(*) AS amount FROM blog_user WHERE deleted_at IS NULL AND (created_at AT TIME ZONE 'Asia/Shanghai')::date < #{startDate}
UNION ALL
SELECT NULL::date AS event_date, 'publishedArticles' AS metric, COUNT(*) AS amount FROM blog_article WHERE published_at IS NOT NULL AND (published_at AT TIME ZONE 'Asia/Shanghai')::date < #{startDate}
UNION ALL
SELECT NULL::date AS event_date, 'comments' AS metric, COUNT(*) AS amount FROM blog_comment WHERE status = 'APPROVED' AND (created_at AT TIME ZONE 'Asia/Shanghai')::date < #{startDate}
UNION ALL
SELECT NULL::date AS event_date, 'messages' AS metric, COUNT(*) AS amount FROM blog_message_board WHERE status = 'APPROVED' AND (created_at AT TIME ZONE 'Asia/Shanghai')::date < #{startDate}
UNION ALL
SELECT NULL::date AS event_date, 'likes' AS metric, COUNT(*) AS amount FROM blog_article_like WHERE (created_at AT TIME ZONE 'Asia/Shanghai')::date < #{startDate}
UNION ALL
SELECT NULL::date AS event_date, 'views' AS metric, COALESCE(SUM(view_count), 0) AS amount FROM blog_article_daily_stat WHERE stat_date < #{startDate}
